<template><AppShell><header class="page-head"><span class="eyebrow"><UserRound :size="15" />LEARNER CENTER</span><h1>我的</h1><p>管理画像、查看学习证据与效果评估。</p></header>
  <section class="user-band"><img :src="`${baseUrl}app-icon.png`" alt="" /><div><strong>{{ user.displayName||user.username||'学习者' }}</strong><span>{{ user.email||user.username||'已登录' }}</span></div><span class="verified"><ShieldCheck :size="16" />已认证</span></section>
  <AsyncState :loading="loading" :error="error" @retry="load"><section class="section-block assessment"><div class="section-head"><div><h2>学习效果</h2><p>结合做题、反馈和任务完成证据</p></div><Gauge :size="22" /></div><template v-if="assessment"><div class="score-line"><strong>{{ assessment.overallScore??assessment.score??'--' }}</strong><span>综合掌握度</span></div><p>{{ assessment.summary||assessment.conclusion||'评估会根据新的学习反馈持续更新。' }}</p><div v-if="adjustments.length" class="adjustments"><span v-for="item in adjustments.slice(0,3)" :key="String(item)">{{ item.title||item.action||String(item) }}</span></div></template><p v-else>完成学习任务并提交反馈后，这里会形成效果评估。</p></section>
  <section class="account-list"><RouterLink to="/profile"><ScanFace :size="20" /><span><b>学习画像</b><small>{{ profile?`${profile.profileName||'当前画像'} v${profile.version||1}`:'尚未完成' }}</small></span><ChevronRight :size="18" /></RouterLink><RouterLink to="/profile/collect"><MessagesSquare :size="20" /><span><b>对话更新</b><small>让画像随学习证据持续更新</small></span><ChevronRight :size="18" /></RouterLink><RouterLink to="/resources"><History :size="20" /><span><b>历史任务</b><small>共 {{ taskCount }} 个服务端任务</small></span><ChevronRight :size="18" /></RouterLink></section>
  </AsyncState>
  <section class="section-block settings"><button v-if="installReady" class="secondary-btn full-btn" @click="install"><Download :size="18" />安装到手机桌面</button><button class="danger-btn full-btn" @click="signOut"><LogOut :size="18" />退出登录</button></section>
  </AppShell></template>
<script setup>
import { computed,onBeforeUnmount,onMounted,ref } from 'vue';import { useRouter,RouterLink } from 'vue-router';import { ChevronRight,Download,Gauge,History,LogOut,MessagesSquare,ScanFace,ShieldCheck,UserRound } from 'lucide-vue-next';import AppShell from '../components/AppShell.vue';import AsyncState from '../components/AsyncState.vue';import { getEffectAssessment,getProfiles,getTaskHistory,logout } from '../services/api.js';import { authState,clearAuthSession } from '../stores/auth.js';import { activeProfile,taskList } from '../utils/data.js'
const router=useRouter(),user=computed(()=>authState.user),loading=ref(true),error=ref(''),profile=ref(null),taskCount=ref(0),assessment=ref(null),installPrompt=ref(null),installReady=ref(false);const adjustments=computed(()=>assessment.value?.recommendations||assessment.value?.pathAdjustmentPlan?.adjustments||[])
const baseUrl=import.meta.env.BASE_URL
async function load(){loading.value=true;error.value='';try{const [p,t]=await Promise.all([getProfiles(),getTaskHistory(100)]);profile.value=activeProfile(p);taskCount.value=taskList(t).length;if(profile.value){const a=await getEffectAssessment(profile.value.id).catch(()=>null);assessment.value=a?.data?.assessment||a?.assessment||null}}catch(e){error.value=e.message}finally{loading.value=false}}
function onInstall(e){e.preventDefault();installPrompt.value=e;installReady.value=true}async function install(){await installPrompt.value?.prompt();installPrompt.value=null;installReady.value=false}async function signOut(){try{await logout()}catch{}clearAuthSession();await router.replace('/login')}
onMounted(()=>{load();window.addEventListener('beforeinstallprompt',onInstall)});onBeforeUnmount(()=>window.removeEventListener('beforeinstallprompt',onInstall))
</script>
<style scoped>.user-band{display:grid;grid-template-columns:58px minmax(0,1fr) auto;align-items:center;gap:13px;padding:16px;border:1px solid #dce5e0;border-radius:7px;background:white}.user-band img{width:58px;height:58px;border-radius:50%;object-fit:cover}.user-band strong,.user-band>div span{display:block}.user-band strong{font-size:16px}.user-band>div span{margin-top:5px;color:#738078;font-size:10px}.verified{min-height:28px;display:flex;align-items:center;gap:4px;padding:5px 7px;border-radius:4px;background:#edf5f1;color:#176f4b;font-size:9px;font-weight:750}.account-list{margin-top:12px;border:1px solid #dce5e0;border-radius:7px;background:white;overflow:hidden}.account-list a{min-height:68px;display:grid;grid-template-columns:32px minmax(0,1fr) 20px;align-items:center;gap:8px;padding:11px 14px;border-bottom:1px solid #dce5e0;color:#176f4b}.account-list a:last-child{border-bottom:0}.account-list b,.account-list small{display:block}.account-list b{color:#26372f;font-size:13px}.account-list small{margin-top:4px;color:#76837d;font-size:9px}.assessment{margin-top:12px;border-top-color:#a16f19}.assessment>.section-head>svg{color:#a16f19}.score-line{display:flex;align-items:end;gap:10px}.score-line strong{color:#176f4b;font-size:38px;line-height:1}.score-line span{color:#718078;font-size:10px}.assessment>p{color:#53665c;font-size:12px;line-height:1.65}.adjustments{display:grid;gap:6px}.adjustments span{padding:8px 10px;background:#edf5f1;color:#476056;font-size:10px}.settings{display:grid;gap:9px}@media (max-width:370px){.user-band{grid-template-columns:50px minmax(0,1fr)}.user-band img{width:50px;height:50px}.verified{grid-column:2;justify-self:start}}</style>
